 * A lightweight, high-performance conversation minimap & timeline progress bar.
 */
(function () {
  'use strict';

  // Prevent multiple initializations
  if (window.__AGY_VOYAGER_INITIALIZED__) return;
  window.__AGY_VOYAGER_INITIALIZED__ = true;

  console.log('[Voyager] Initializing Antigravity Timeline Navigator...');

  // 1. Inject Styles
  function injectStyles() {
    if (document.getElementById('agy-voyager-style')) return;
    const style = document.createElement('style');
    style.id = 'agy-voyager-style';
    style.textContent = `
      #agy-voyager-rail {
        position: fixed;
        right: 14px;
        top: 50%;
        transform: translateY(-50%);
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 8px;
        z-index: 999999;
        background: rgba(24, 25, 29, 0.72);
        backdrop-filter: blur(14px);
        -webkit-backdrop-filter: blur(14px);
        padding: 8px 5px;
        border-radius: 20px;
        border: 1px solid rgba(255, 255, 255, 0.12);
        box-shadow: 0 8px 30px rgba(0, 0, 0, 0.35);
        opacity: 0.4;
        transition: opacity 0.3s ease, transform 0.2s ease;
        max-height: 75vh;
        user-select: none;
      }
      #agy-voyager-rail:hover {
        opacity: 1;
      }

      .voyager-nav-btn {
        width: 20px;
        height: 20px;
        display: flex;
        align-items: center;
        justify-content: center;
        cursor: pointer;
        color: rgba(255, 255, 255, 0.6);
        font-size: 11px;
        border-radius: 50%;
        transition: all 0.2s ease;
      }
      .voyager-nav-btn:hover {
        color: #ffffff;
        background: rgba(255, 255, 255, 0.15);
        transform: scale(1.15);
      }

      .voyager-dots-list {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 7px;
        overflow-y: auto;
        overflow-x: hidden;
        max-height: calc(75vh - 60px);
        padding: 4px 2px;
        scrollbar-width: none;
      }
      .voyager-dots-list::-webkit-scrollbar {
        display: none;
      }

      .voyager-dot {
        width: 8px;
        height: 8px;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.3);
        cursor: pointer;
        position: relative;
        transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
        flex-shrink: 0;
      }
      .voyager-dot:hover {
        background: #3b82f6;
        transform: scale(1.5);
      }
      .voyager-dot.active {
        background: #10b981;
        transform: scale(1.4);
        box-shadow: 0 0 10px rgba(16, 185, 129, 0.85);
      }

      /* Hover Tooltip */
      .voyager-dot .voyager-tooltip {
        position: absolute;
        right: 22px;
        top: 50%;
        transform: translateY(-50%) translateX(6px);
        background: rgba(20, 20, 24, 0.94);
        color: #f1f5f9;
        padding: 6px 12px;
        font-size: 11px;
        line-height: 1.4;
        border-radius: 8px;
        white-space: nowrap;
        pointer-events: none;
        opacity: 0;
        visibility: hidden;
        transition: opacity 0.18s ease, transform 0.18s ease, visibility 0.18s;
        border: 1px solid rgba(255, 255, 255, 0.15);
        box-shadow: 0 4px 18px rgba(0, 0, 0, 0.45);
        max-width: 280px;
        overflow: hidden;
        text-overflow: ellipsis;
      }
      .voyager-dot:hover .voyager-tooltip {
        opacity: 1;
        visibility: visible;
        transform: translateY(-50%) translateX(0);
      }
      .voyager-tooltip-tag {
        color: #60a5fa;
        font-weight: 600;
        margin-right: 5px;
      }
    `;
    (document.head || document.documentElement).appendChild(style);
  }

  // 2. Build DOM Components
  let railElement = null;
  let dotsContainer = null;
  let activeObserver = null;
  let indexedMessages = [];

  function createRail() {
    if (document.getElementById('agy-voyager-rail')) {
      railElement = document.getElementById('agy-voyager-rail');
      dotsContainer = railElement.querySelector('.voyager-dots-list');
      return;
    }

    railElement = document.createElement('div');
    railElement.id = 'agy-voyager-rail';
    railElement.style.display = 'none'; // Hidden until >= 2 items

    // Top Jump Button (To Top)
    const topBtn = document.createElement('div');
    topBtn.className = 'voyager-nav-btn';
    topBtn.innerHTML = '▲';
    topBtn.title = '跳转到对话顶部';
    topBtn.onclick = () => {
      const scrollable = findScrollContainer();
      if (scrollable) {
        scrollable.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
    };

    // Dots Container
    dotsContainer = document.createElement('div');
    dotsContainer.className = 'voyager-dots-list';

    // Bottom Jump Button (To Bottom)
    const bottomBtn = document.createElement('div');
    bottomBtn.className = 'voyager-nav-btn';
    bottomBtn.innerHTML = '▼';
    bottomBtn.title = '跳转到最新回答';
    bottomBtn.onclick = () => {
      const scrollable = findScrollContainer();
      if (scrollable) {
        scrollable.scrollTo({ top: scrollable.scrollHeight, behavior: 'smooth' });
      } else {
        window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
      }
    };

    railElement.appendChild(topBtn);
    railElement.appendChild(dotsContainer);
    railElement.appendChild(bottomBtn);

    document.body.appendChild(railElement);
  }

  // 3. Find Main Scroll Container
  function findScrollContainer() {
    // Try finding the scroll container holding messages
    const candidates = document.querySelectorAll('main, [role="main"], div');
    for (let i = 0; i < candidates.length; i++) {
      const el = candidates[i];
      if (el === railElement || railElement.contains(el)) continue;
      const style = window.getComputedStyle(el);
      const isScroll = (style.overflowY === 'auto' || style.overflowY === 'scroll') && el.scrollHeight > el.clientHeight + 50;
      if (isScroll && el.clientHeight > 200) {
        return el;
      }
    }
    return window;
  }

  // 4. Message Detection Engine (Multi-strategy)
  function detectConversationItems() {
    // Strategy A: Role attributes
    const roleSelectors = [
      '[data-message-author-role="user"]',
      '[data-role="user"]',
      '[data-turn="user"]',
      '.user-message',
      '.chat-turn-user'
    ];
    for (const sel of roleSelectors) {
      const found = document.querySelectorAll(sel);
      if (found.length >= 2) {
        return Array.from(found);
      }
    }

    // Strategy B: Turn/Bubble generic structures
    const turnSelectors = [
      '.chat-turn',
      '.conversation-turn',
      '[class*="turn-"]',
      '[class*="message-bubble"]',
      '[class*="ChatMessage"]',
      '[class*="UserQuery"]'
    ];
    for (const sel of turnSelectors) {
      const found = document.querySelectorAll(sel);
      if (found.length >= 2) {
        return Array.from(found).filter(n => !n.closest('#agy-voyager-rail'));
      }
    }

    // Strategy C: Inspect articles or main message rows
    const articles = document.querySelectorAll('main article, [role="main"] article');
    if (articles.length >= 2) {
      return Array.from(articles);
    }

    // Strategy D: Fallback - Detect large blocks inside conversation pane
    const scrollable = findScrollContainer();
    if (scrollable && scrollable !== window) {
      const children = Array.from(scrollable.children).filter(c => {
        return c !== railElement && c.offsetHeight > 30 && c.innerText && c.innerText.trim().length > 3;
      });
      if (children.length >= 2) {
        return children;
      }
    }

    return [];
  }

  // 5. Refresh Timeline Dots
  function refreshTimeline() {
    if (!dotsContainer) createRail();

    const messages = detectConversationItems();
    indexedMessages = messages;

    // Show/hide rail based on item count
    if (messages.length < 2) {
      railElement.style.display = 'none';
      return;
    } else {
      railElement.style.display = 'flex';
    }

    dotsContainer.innerHTML = '';

    if (activeObserver) activeObserver.disconnect();
    activeObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const idx = indexedMessages.indexOf(entry.target);
          if (idx !== -1) {
            const dots = dotsContainer.querySelectorAll('.voyager-dot');
            dots.forEach((dot, dIdx) => {
              dot.classList.toggle('active', dIdx === idx);
            });
          }
        }
      });
    }, {
      root: findScrollContainer() === window ? null : findScrollContainer(),
      rootMargin: '-15% 0px -55% 0px',
      threshold: 0.1
    });

    messages.forEach((msgNode, idx) => {
      activeObserver.observe(msgNode);

      const dot = document.createElement('div');
      dot.className = 'voyager-dot';

      // Tooltip Text Preview
      const rawText = (msgNode.innerText || '').replace(/\s+/g, ' ').trim();
      const previewText = rawText.length > 36 ? rawText.slice(0, 36) + '...' : (rawText || `问答 #${idx + 1}`);

      const tooltip = document.createElement('div');
      tooltip.className = 'voyager-tooltip';
      tooltip.innerHTML = `<span class="voyager-tooltip-tag">#${idx + 1}</span>${escapeHTML(previewText)}`;
      dot.appendChild(tooltip);

      // Smooth Scroll on Click
      dot.onclick = (e) => {
        e.stopPropagation();
        msgNode.scrollIntoView({ behavior: 'smooth', block: 'start' });
        // Briefly highlight
        dot.classList.add('active');
      };

      dotsContainer.appendChild(dot);
    });
  }

  function escapeHTML(str) {
    return str.replace(/[&<>"']/g, m => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    })[m]);
  }

  // 6. Non-intrusive DOM Observer (ChildList only, Debounced 300ms)
  let debounceTimer = null;
  function startDOMWatcher() {
    const observer = new MutationObserver(() => {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(refreshTimeline, 300);
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true
    });
  }

  // 7. Bootstrapping
  function init() {
    injectStyles();
    createRail();
    refreshTimeline();
    startDOMWatcher();
    console.log('[Voyager] Antigravity Timeline Navigator is fully ready.');
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

