/**
 * Antigravity 2.0 Voyager Timeline Navigator v2.0 (Ultra-Robust Edition)
 * A lightweight, high-performance conversation minimap & timeline navigation bar.
 */
(function () {
  'use strict';

  if (window.__AGY_VOYAGER_INITIALIZED__) {
    // If already exists, re-trigger refresh
    if (window.__AGY_VOYAGER_REFRESH__) window.__AGY_VOYAGER_REFRESH__();
    return;
  }
  window.__AGY_VOYAGER_INITIALIZED__ = true;

  console.log('[Voyager v2.0] Initializing Timeline Navigator...');

  // 1. Inject Styles
  function injectStyles() {
    let style = document.getElementById('agy-voyager-style');
    if (!style) {
      style = document.createElement('style');
      style.id = 'agy-voyager-style';
      document.head.appendChild(style);
    }
    style.textContent = `
      #agy-voyager-rail {
        position: fixed !important;
        right: 12px !important;
        top: 50% !important;
        transform: translateY(-50%) !important;
        display: flex !important;
        flex-direction: column !important;
        align-items: center !important;
        gap: 8px !important;
        z-index: 2147483647 !important;
        background: rgba(22, 24, 29, 0.82) !important;
        backdrop-filter: blur(14px) !important;
        -webkit-backdrop-filter: blur(14px) !important;
        padding: 8px 6px !important;
        border-radius: 22px !important;
        border: 1px solid rgba(255, 255, 255, 0.15) !important;
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.45) !important;
        opacity: 0.65;
        transition: opacity 0.25s ease, transform 0.2s ease;
        max-height: 80vh;
        user-select: none !important;
      }
      #agy-voyager-rail:hover {
        opacity: 1 !important;
      }

      .voyager-nav-btn {
        width: 22px;
        height: 22px;
        display: flex;
        align-items: center;
        justify-content: center;
        cursor: pointer;
        color: rgba(255, 255, 255, 0.7);
        font-size: 11px;
        border-radius: 50%;
        transition: all 0.2s ease;
      }
      .voyager-nav-btn:hover {
        color: #ffffff;
        background: rgba(255, 255, 255, 0.2);
        transform: scale(1.15);
      }

      .voyager-dots-list {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 8px;
        overflow-y: auto;
        overflow-x: hidden;
        max-height: calc(80vh - 65px);
        padding: 4px 2px;
        scrollbar-width: none;
      }
      .voyager-dots-list::-webkit-scrollbar {
        display: none;
      }

      .voyager-dot {
        width: 9px;
        height: 9px;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.35);
        cursor: pointer;
        position: relative;
        transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
        flex-shrink: 0;
      }
      .voyager-dot:hover {
        background: #3b82f6;
        transform: scale(1.6);
      }
      .voyager-dot.active {
        background: #10b981;
        transform: scale(1.4);
        box-shadow: 0 0 10px rgba(16, 185, 129, 0.9);
      }

      /* Hover Tooltip */
      .voyager-dot .voyager-tooltip {
        position: absolute;
        right: 22px;
        top: 50%;
        transform: translateY(-50%) translateX(6px);
        background: rgba(18, 19, 23, 0.96);
        color: #f8fafc;
        padding: 6px 12px;
        font-size: 11px;
        line-height: 1.4;
        border-radius: 8px;
        white-space: nowrap;
        pointer-events: none;
        opacity: 0;
        visibility: hidden;
        transition: opacity 0.15s ease, transform 0.15s ease;
        border: 1px solid rgba(255, 255, 255, 0.16);
        box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
        max-width: 320px;
        overflow: hidden;
        text-overflow: ellipsis;
      }
      .voyager-dot:hover .voyager-tooltip {
        opacity: 1;
        visibility: visible;
        transform: translateY(-50%) translateX(0);
      }
      .voyager-tooltip-tag {
        color: #60a5fa;
        font-weight: 600;
        margin-right: 6px;
      }
    `;
  }

  // 2. Build DOM Components
  let railElement = null;
  let dotsContainer = null;
  let activeObserver = null;
  let indexedMessages = [];

  function createRail() {
    if (document.getElementById('agy-voyager-rail')) {
      railElement = document.getElementById('agy-voyager-rail');
      dotsContainer = railElement.querySelector('.voyager-dots-list');
      return;
    }

    railElement = document.createElement('div');
    railElement.id = 'agy-voyager-rail';

    // Top Jump Button
    const topBtn = document.createElement('div');
    topBtn.className = 'voyager-nav-btn';
    topBtn.innerHTML = '▲';
    topBtn.title = '跳转到对话顶部';
    topBtn.onclick = () => {
      const scrollable = findScrollContainer();
      if (scrollable && scrollable.scrollTo) {
        scrollable.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
    };

    // Dots Container
    dotsContainer = document.createElement('div');
    dotsContainer.className = 'voyager-dots-list';

    // Bottom Jump Button
    const bottomBtn = document.createElement('div');
    bottomBtn.className = 'voyager-nav-btn';
    bottomBtn.innerHTML = '▼';
    bottomBtn.title = '跳转到最新回答';
    bottomBtn.onclick = () => {
      const scrollable = findScrollContainer();
      if (scrollable && scrollable.scrollTo) {
        scrollable.scrollTo({ top: scrollable.scrollHeight || 999999, behavior: 'smooth' });
      } else {
        window.scrollTo({ top: document.body.scrollHeight || 999999, behavior: 'smooth' });
      }
    };

    railElement.appendChild(topBtn);
    railElement.appendChild(dotsContainer);
    railElement.appendChild(bottomBtn);

    document.body.appendChild(railElement);
  }

  // 3. Find Deepest Scrollable Container
  function findScrollContainer() {
    const all = document.querySelectorAll('*');
    let best = window;
    let maxScroll = 0;
    for (let i = 0; i < all.length; i++) {
      const el = all[i];
      if (el === railElement || (railElement && railElement.contains(el))) continue;
      const style = window.getComputedStyle(el);
      if ((style.overflowY === 'auto' || style.overflowY === 'scroll') && el.scrollHeight > el.clientHeight + 50) {
        if (el.scrollHeight > maxScroll && el.clientHeight > 150) {
          maxScroll = el.scrollHeight;
          best = el;
        }
      }
    }
    return best;
  }

  // 4. Multi-strategy Message Sniffer
  function detectConversationItems() {
    // Strategy 1: Look for action bar triggers (copy buttons)
    const copyIcons = Array.from(document.querySelectorAll('button, svg, [role="button"]')).filter(el => {
      const t = (el.getAttribute('title') || el.getAttribute('aria-label') || el.innerText || '').toLowerCase();
      return t.includes('copy') || t.includes('复制');
    });

    if (copyIcons.length >= 1) {
      const turns = [];
      copyIcons.forEach(btn => {
        let p = btn.parentElement;
        while (p && p !== document.body && p !== document.documentElement) {
          if (p.offsetHeight > 40 && p.offsetWidth > 150) {
            // Find outer message container
            if (!turns.includes(p) && !turns.some(existing => existing.contains(p))) {
              turns.push(p);
            }
            break;
          }
          p = p.parentElement;
        }
      });
      if (turns.length >= 1) {
        return turns.filter(n => !n.closest('#agy-voyager-rail'));
      }
    }

    // Strategy 2: Common chat turn selectors
    const selectors = [
      '[data-message-author-role]',
      '.chat-turn',
      '.message-row',
      '.conversation-turn',
      '[class*="message"]',
      '[class*="turn-"]'
    ];
    for (const sel of selectors) {
      const matches = document.querySelectorAll(sel);
      if (matches.length >= 2) {
        return Array.from(matches).filter(n => !n.closest('#agy-voyager-rail') && n.offsetHeight > 30);
      }
    }

    // Strategy 3: Find headings (H1, H2, H3) inside conversation for TOC navigation
    const headings = document.querySelectorAll('h1, h2, h3');
    if (headings.length >= 2) {
      return Array.from(headings).filter(h => !h.closest('#agy-voyager-rail') && h.innerText.trim().length > 1);
    }

    // Strategy 4: Fallback to direct children of scroll container
    const scrollable = findScrollContainer();
    if (scrollable && scrollable !== window) {
      const items = Array.from(scrollable.children).filter(c => {
        return c !== railElement && c.offsetHeight > 40 && c.innerText && c.innerText.trim().length > 5;
      });
      if (items.length >= 1) return items;
    }

    return [];
  }

  // 5. Refresh Timeline Dots
  function refreshTimeline() {
    if (!dotsContainer) createRail();

    const messages = detectConversationItems();
    indexedMessages = messages;

    dotsContainer.innerHTML = '';

    if (activeObserver) activeObserver.disconnect();
    const scrollParent = findScrollContainer();
    activeObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const idx = indexedMessages.indexOf(entry.target);
          if (idx !== -1) {
            const dots = dotsContainer.querySelectorAll('.voyager-dot');
            dots.forEach((dot, dIdx) => {
              dot.classList.toggle('active', dIdx === idx);
            });
          }
        }
      });
    }, {
      root: scrollParent === window ? null : scrollParent,
      rootMargin: '-15% 0px -50% 0px',
      threshold: 0.1
    });

    messages.forEach((msgNode, idx) => {
      activeObserver.observe(msgNode);

      const dot = document.createElement('div');
      dot.className = 'voyager-dot';

      let rawText = (msgNode.innerText || '').replace(/\s+/g, ' ').trim();
      if (rawText.length > 32) rawText = rawText.slice(0, 32) + '...';
      if (!rawText) rawText = `问答 #${idx + 1}`;

      const tooltip = document.createElement('div');
      tooltip.className = 'voyager-tooltip';
      tooltip.innerHTML = `<span class="voyager-tooltip-tag">#${idx + 1}</span>${escapeHTML(rawText)}`;
      dot.appendChild(tooltip);

      dot.onclick = (e) => {
        e.stopPropagation();
        msgNode.scrollIntoView({ behavior: 'smooth', block: 'start' });
        dot.classList.add('active');
      };

      dotsContainer.appendChild(dot);
    });

    // If no nodes found yet, put a single placeholder dot
    if (messages.length === 0) {
      const dummyDot = document.createElement('div');
      dummyDot.className = 'voyager-dot active';
      dummyDot.title = 'Voyager 就绪 (等待消息)';
      dotsContainer.appendChild(dummyDot);
    }
  }

  function escapeHTML(str) {
    return str.replace(/[&<>"']/g, m => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    })[m]);
  }

  // 6. DOM Mutation Watcher (Debounced 350ms, ChildList only)
  let debounceTimer = null;
  function startDOMWatcher() {
    const observer = new MutationObserver(() => {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(refreshTimeline, 350);
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true
    });
  }

  // 7. Initialize
  function init() {
    injectStyles();
    createRail();
    refreshTimeline();
    startDOMWatcher();
    window.__AGY_VOYAGER_REFRESH__ = refreshTimeline;
    console.log('[Voyager v2.0] Timeline Navigator is fully rendered.');
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

