  let railElement = null;
  let dotsContainer = null;
  let targetPrompts = [];
  let currentActiveIndex = 0;

  function findScrollContainer() {
    const all = document.querySelectorAll('*');
    let best = window;
    let maxScroll = 0;
    for (let i = 0; i < all.length; i++) {
      const el = all[i];
      if (el === railElement || (railElement && railElement.contains(el))) continue;
      const s = window.getComputedStyle(el);
      if ((s.overflowY === 'auto' || s.overflowY === 'scroll') && el.scrollHeight > el.clientHeight + 60) {
        if (el.scrollHeight > maxScroll && el.clientHeight > 180) {
          maxScroll = el.scrollHeight;
          best = el;
        }
      }
    }
    return best;
  }

  function scrollToNode(node) {
    if (!node) return;
    node.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  // 2. Identify User Prompt Cards accurately
  function findUserPromptNodes() {
    const prompts = [];

    // Find all assistant response action bars (Copy buttons)
    const copyIcons = Array.from(document.querySelectorAll('button, svg, [role="button"]')).filter(el => {
      const t = (el.getAttribute('title') || el.getAttribute('aria-label') || el.innerText || '').toLowerCase();
      return t.includes('copy') || t.includes('复制');
    });

    copyIcons.forEach(btn => {
      let assistantBlock = btn.parentElement;
      while (assistantBlock && assistantBlock !== document.body && assistantBlock !== document.documentElement) {
        if (assistantBlock.offsetHeight > 40 && assistantBlock.offsetWidth > 180) {
          break;
        }
        assistantBlock = assistantBlock.parentElement;
      }

      if (assistantBlock) {
        // The previous sibling in chat flow is the user prompt card
        let prev = assistantBlock.previousElementSibling;
        while (prev && prev.offsetHeight < 15) {
          prev = prev.previousElementSibling;
        }
        if (prev && !prompts.includes(prev)) {
          prompts.push(prev);
        } else if (!prompts.includes(assistantBlock)) {
          // Fallback to assistant block if no separate prompt element
          prompts.push(assistantBlock);
        }
      }
    });

    if (prompts.length >= 1) return prompts;

    // Fallback: look for common selectors
    const selectors = [
      '[data-message-author-role="user"]',
      '.user-message',
      '[class*="UserMessage"]',
      '.chat-turn',
      '.message-row'
    ];
    for (const sel of selectors) {
      const matches = document.querySelectorAll(sel);
      if (matches.length >= 1) {
        return Array.from(matches).filter(n => !n.closest('#agy-voyager-rail') && n.offsetHeight > 20);
