    };

    // Button 2: Single Up Arrow (To Previous Turn)
    const prevBtn = document.createElement('div');
    prevBtn.className = 'voyager-nav-btn';
    prevBtn.innerHTML = '▲';
    prevBtn.title = '去上一个回复';
