    nextBtn.innerHTML = '▼';
    nextBtn.title = '去下一个回复';
    nextBtn.onclick = () => {
      if (targetPrompts.length === 0) return;
      const targetIdx = Math.min(targetPrompts.length - 1, currentActiveIndex + 1);
      scrollToNode(targetPrompts[targetIdx]);
    };

    // Button 4: Double Down Arrow (To Latest Turn)
    const lastBtn = document.createElement('div');
    lastBtn.className = 'voyager-nav-btn double';
    lastBtn.innerHTML = '▼▼';
    lastBtn.title = '去最新回复';
    lastBtn.onclick = () => {
      if (targetPrompts.length > 0) {
        scrollToNode(targetPrompts[targetPrompts.length - 1]);
      } else {
        const sc = findScrollContainer();
        sc.scrollTo ? sc.scrollTo({ top: 999999, behavior: 'smooth' }) : window.scrollTo({ top: 999999, behavior: 'smooth' });
      }
    };

    railElement.appendChild(firstBtn);
    railElement.appendChild(prevBtn);
    railElement.appendChild(dividerTop);
    railElement.appendChild(dotsContainer);
    railElement.appendChild(dividerBtm);
    railElement.appendChild(nextBtn);
    railElement.appendChild(lastBtn);

    document.body.appendChild(railElement);
  }

  // 4. Update Active Dot smoothly without flickering
  function updateActiveIndex(idx) {
    if (idx === currentActiveIndex && dotsContainer.querySelector('.voyager-dot.active')) return;
    currentActiveIndex = idx;
    const dots = dotsContainer.querySelectorAll('.voyager-dot');
    dots.forEach((dot, i) => {
      if (i === idx) {
        dot.classList.add('active');
      } else {
        dot.classList.remove('active');
      }
    });
  }

  // 5. Render Timeline Dots
  function render() {
    buildRail();
    targetPrompts = findUserPromptNodes();
    dotsContainer.innerHTML = '';

    if (targetPrompts.length === 0) {
      const singleDot = document.createElement('div');
      singleDot.className = 'voyager-dot active';
      dotsContainer.appendChild(singleDot);
      return;
    }

    targetPrompts.forEach((promptNode, idx) => {
      const dot = document.createElement('div');
      dot.className = 'voyager-dot';
      if (idx === currentActiveIndex) {
        dot.classList.add('active');
      }

      // Click to accurately scroll to that user prompt
      dot.onclick = (e) => {
        e.stopPropagation();
        updateActiveIndex(idx);
        scrollToNode(promptNode);
      };

      dotsContainer.appendChild(dot);
    });

    syncActiveByScroll();
  }

  // Calculate current active turn based on viewport top position
  function syncActiveByScroll() {
    if (targetPrompts.length === 0) return;
    const scrollContainer = findScrollContainer();
    const containerTop = scrollContainer === window ? 0 : scrollContainer.getBoundingClientRect().top;

    let closestIdx = 0;
    let minDistance = Infinity;

    targetPrompts.forEach((node, idx) => {
      const rect = node.getBoundingClientRect();
      // Distance to upper 25% of viewport
      const distance = Math.abs(rect.top - (containerTop + 100));
      if (rect.top <= containerTop + 250 && distance < minDistance) {
        minDistance = distance;
        closestIdx = idx;
      }
    });

    updateActiveIndex(closestIdx);
  }

  // Scroll listener on container for smooth, solid green active state
  let scrollTimer = null;
  function bindScrollWatcher() {
    const sc = findScrollContainer();
    const target = sc === window ? window : sc;
    target.addEventListener('scroll', () => {
      if (scrollTimer) return;
      scrollTimer = setTimeout(() => {
        scrollTimer = null;
        syncActiveByScroll();
      }, 80);
    }, { passive: true });
  }

  // 6. DOM Mutation Watcher (Debounced, ChildList only)
  let domTimer = null;
  function startDOMWatcher() {
    const observer = new MutationObserver(() => {
      clearTimeout(domTimer);
      domTimer = setTimeout(render, 300);
    });
    observer.observe(document.body, { childList: true, subtree: true });
  }

  // Initialize
  function init() {
    injectStyles();
    buildRail();
    render();
    bindScrollWatcher();
    startDOMWatcher();
    window.__AGY_VOYAGER_V3__ = { refresh: render };
    console.log('[Voyager v3.0] Ready with Double/Single Arrows & Solid Green Dots.');
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

