  nextBtn.onclick = () => {
    scrollToTurn(currentActive + 1);
  };

  // Button 4: Double Down (Latest turn)
  const lastBtn = document.createElement('div');
  lastBtn.className = 'v-btn double';
  lastBtn.innerText = '▼▼';
  lastBtn.title = '去最新回复';
  lastBtn.onclick = () => {
    const sc = getChatScroll();
    if (sc) sc.scrollTo({ top: sc.scrollHeight, behavior: 'smooth' });
    updateActive(turnsCache.length - 1);
  };

  rail.append(firstBtn, prevBtn, l1, dotsContainer, l2, nextBtn, lastBtn);
  document.body.appendChild(rail);

  function updateActive(idx) {
    currentActive = idx;
    dotsContainer.querySelectorAll('.v-dot').forEach((d, i) => {
      d.classList.toggle('active', i === idx);
    });
  }

  function render() {
    turnsCache = getTurns();
    dotsContainer.innerHTML = '';

    if (turnsCache.length === 0) {
      const d = document.createElement('div');
      d.className = 'v-dot active';
      dotsContainer.appendChild(d);
      return;
    }

    turnsCache.forEach((turn, i) => {
      const d = document.createElement('div');
      d.className = 'v-dot' + (i === currentActive ? ' active' : '');
      d.onclick = (e) => {
        e.stopPropagation();
        scrollToTurn(i);
      };
      dotsContainer.appendChild(d);
    });
  }

  function syncScroll() {
    const sc = getChatScroll();
    if (!sc || turnsCache.length === 0) return;
    const curTop = sc.scrollTop;
    let bestIdx = 0;
    for (let i = 0; i < turnsCache.length; i++) {
      if (turnsCache[i].offsetTop <= curTop + 150) {
        bestIdx = i;
      }
    }
    updateActive(bestIdx);
  }

  // Hook scroll event
  let scrollAttached = false;
  function attachScroll() {
    const sc = getChatScroll();
    if (sc && !scrollAttached) {
      scrollAttached = true;
      let timer = null;
      sc.addEventListener('scroll', () => {
        if (timer) return;
        timer = setTimeout(() => {
          timer = null;
          syncScroll();
        }, 50);
      }, { passive: true });
    }
  }

  // Hook mutation
  let mTimer = null;
  const watcher = new MutationObserver(() => {
    clearTimeout(mTimer);
    mTimer = setTimeout(() => {
      render();
      attachScroll();
      syncScroll();
    }, 300);
  });
  watcher.observe(document.body, { childList: true, subtree: true });

  render();
  attachScroll();
  syncScroll();

  console.log('[Voyager v4.0] Native Accurate Scroll Installed!');
})();

