const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const WORKSPACE_DIR = __dirname;
const EXTRACT_DIR = path.join(WORKSPACE_DIR, 'extracted');
const APP_DIR = 'C:\\Users\\wangRui\\AppData\\Local\\Programs\\antigravity';
const RESOURCES_DIR = path.join(APP_DIR, 'resources');
const ASAR_PATH = path.join(RESOURCES_DIR, 'app.asar');
const TEMP_ASAR = path.join(WORKSPACE_DIR, 'app.asar.temp');

console.log('=== 开始免杀进程安全汉化 + Voyager 部署 ===');

// 1. Clean extract dir
if (fs.existsSync(EXTRACT_DIR)) {
  console.log('正在清理历史解压目录...');
  fs.rmSync(EXTRACT_DIR, { recursive: true, force: true });
}

// 2. Extract current asar
console.log('正在解包当前核心包 app.asar...');
execSync(`npx -y @electron/asar extract "${ASAR_PATH}" "${EXTRACT_DIR}"`, { cwd: WORKSPACE_DIR });
console.log('解包成功！');

// 3. Load localize.js to borrow applyTranslations logic
// We can require or evaluate applyTranslations directly
const localizeCode = fs.readFileSync(path.join(WORKSPACE_DIR, 'localize.js'), 'utf-8');

// Execute applyTranslations in this context
// We extract DOM_TRANSLATOR_INJECTION and applyTranslations
const vm = require('vm');
const sandbox = {
  console,
  fs,
  path,
  WORKSPACE_DIR,
  EXTRACT_DIR,
  log: (msg) => console.log('[Localize] ' + msg),
  replaceInFile: (filePath, target, replacement) => {
    if (!fs.existsSync(filePath)) throw new Error('File not found: ' + filePath);
    const content = fs.readFileSync(filePath, 'utf-8');
    if (!content.includes(target)) {
      console.log('Target not found for replace (may already be replaced):', target.slice(0, 40));
      return;
    }
    fs.writeFileSync(filePath, content.replace(target, replacement), 'utf-8');
    console.log('Successfully replaced in ' + path.basename(filePath));
  }
};

vm.createContext(sandbox);

// Run the script to define functions
vm.runInContext(localizeCode + '\n;applyTranslations();', sandbox);
console.log('汉化与 Voyager 逻辑注入完成！');

// 4. Verify syntax of all modified files
const filesToCheck = [
  path.join(EXTRACT_DIR, 'dist', 'preload.js'),
  path.join(EXTRACT_DIR, 'dist', 'voyager.js'),
  path.join(EXTRACT_DIR, 'dist', 'menu.js'),
  path.join(EXTRACT_DIR, 'dist', 'tray.js')
];

for (const f of filesToCheck) {
  if (fs.existsSync(f)) {
    execSync(`node --check "${f}"`);
    console.log('语法门禁通过: ' + path.basename(f));
  }
}

// 5. Pack to temp asar
if (fs.existsSync(TEMP_ASAR)) fs.unlinkSync(TEMP_ASAR);
console.log('正在重新打包 app.asar...');
execSync(`npx -y @electron/asar pack "${EXTRACT_DIR}" "${TEMP_ASAR}"`, { cwd: WORKSPACE_DIR });
console.log('打包成功！');

// 6. Deploy atomic copy
console.log('正在覆盖部署到系统程序目录...');
fs.copyFileSync(TEMP_ASAR, ASAR_PATH);
fs.unlinkSync(TEMP_ASAR);
console.log('🎉 汉化 + Voyager 已成功永久部署到本地客户端中！');

