import urllib.request, json, asyncio, websockets

async def check():
    with urllib.request.urlopen('http://127.0.0.1:49703/json', timeout=5) as resp:
        targets = json.loads(resp.read().decode())
    target = [t for t in targets if t.get('type') == 'page'][0]

    async with websockets.connect(target['webSocketDebuggerUrl']) as ws:
        expr = '''
        (() => {
          // Check some translated words in sidebar
          const texts = Array.from(document.querySelectorAll('button, a, span, div')).map(el => el.innerText).filter(Boolean);
          const hasChineseNewChat = texts.some(t => t.includes('新建对话') || t.includes('新会话'));
          const hasChineseSettings = texts.some(t => t.includes('设置'));
          const hasHistory = texts.some(t => t.includes('历史对话') || t.includes('会话'));

          const rail = document.getElementById('agy-voyager-rail');

          return {
            hasChineseNewChat: hasChineseNewChat,
            hasChineseSettings: hasChineseSettings,
            hasHistory: hasHistory,
            railHTML: rail ? rail.outerHTML.slice(0, 100) : 'none'
          };
        })()
        '''
        msg = {'id': 1, 'method': 'Runtime.evaluate', 'params': {'expression': expr, 'returnByValue': True}}
        await ws.send(json.dumps(msg))
        res = await ws.recv()
        data = json.loads(res)
        print(json.dumps(data.get('result', {}).get('result', {}).get('value', {}), ensure_ascii=False, indent=2))

asyncio.run(check())
"

