/**
 * Antigravity 2.0 Voyager Timeline Navigator v4.0 (Native Accurate Scroll Edition)
 * - Double Up (▲▲): Go to first turn
 * - Single Up (▲): Go to previous turn
 * - Single Down (▼): Go to next turn
 * - Double Down (▼▼): Go to latest turn
 * - Exact offsetTop scroll inside native isolated scroll container
 * - Solid static green dot, zero flickering, zero tooltips
 */
(function () {
  'use strict';

  // 1. Remove old instance
  const old = document.getElementById('agy-voyager-rail');
  if (old) old.remove();

  // 2. Styles
  let style = document.getElementById('agy-voyager-style');
  if (!style) {
    style = document.createElement('style');
    style.id = 'agy-voyager-style';
    document.head.appendChild(style);
  }
  style.textContent = `
    #agy-voyager-rail {
      position: fixed !important;
      right: 14px !important;
      top: 50% !important;
      transform: translateY(-50%) !important;
      display: flex !important;
      flex-direction: column !important;
      align-items: center !important;
      gap: 5px !important;
      z-index: 2147483647 !important;
      background: rgba(22, 24, 29, 0.88) !important;
      backdrop-filter: blur(14px) !important;
      -webkit-backdrop-filter: blur(14px) !important;
      padding: 7px 4px !important;
      border-radius: 20px !important;
      border: 1px solid rgba(255, 255, 255, 0.16) !important;
      box-shadow: 0 8px 30px rgba(0, 0, 0, 0.45) !important;
      opacity: 0.75;
      transition: opacity 0.2s ease;
      max-height: 82vh;
      user-select: none !important;
    }
    #agy-voyager-rail:hover {
      opacity: 1 !important;
    }

    .v-btn {
      width: 22px;
      height: 20px;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      color: rgba(255, 255, 255, 0.75);
      font-size: 11px;
      font-weight: bold;
      line-height: 1;
      border-radius: 4px;
      transition: background 0.15s, color 0.15s, transform 0.15s;
    }
    .v-btn:hover {
      color: #fff;
      background: rgba(255, 255, 255, 0.2);
      transform: scale(1.15);
    }
    .v-btn.double {
      font-size: 9px;
      letter-spacing: -1px;
    }

    .v-line {
      width: 12px;
      height: 1px;
      background: rgba(255, 255, 255, 0.12);
      margin: 2px 0;
    }

    .v-dots {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 8px;
      max-height: calc(82vh - 120px);
      overflow-y: auto;
      padding: 4px 2px;
      scrollbar-width: none;
    }
    .v-dots::-webkit-scrollbar {
      display: none;
    }

    .v-dot {
      width: 9px;
      height: 9px;
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.35);
      cursor: pointer;
      transition: background 0.15s ease, transform 0.15s ease;
      flex-shrink: 0;
    }
    .v-dot:hover {
      background: #3b82f6;
      transform: scale(1.4);
    }

    /* Solid static green - NEVER blinks */
    .v-dot.active {
      background: #10b981 !important;
      transform: scale(1.35) !important;
      box-shadow: none !important;
      animation: none !important;
    }
  `;

  // 3. Helpers to find accurate Chat Scroll container and Turns
  function getChatScroll() {
    return document.querySelector('.overflow-y-auto.isolate') ||
           document.querySelector('.md-table-bleed') ||
           document.querySelector('[class*="overflow-y-auto"][class*="isolate"]');
  }

  function getTurns() {
    const sc = getChatScroll();
    if (!sc) return [];
    const list = sc.querySelector('.relative.flex.flex-col.gap-y-3') || sc.querySelector('.relative.w-full');
    if (list) {
      const items = Array.from(list.querySelectorAll(':scope > div.flex.items-start, :scope > div[class*="flex"][class*="items-start"]'));
      if (items.length > 0) return items;
    }
    const userPrompts = Array.from(sc.querySelectorAll('.md-sticky-message-bleed, [class*="user-input-step"]'));
    if (userPrompts.length > 0) return userPrompts;
    return [];
  }

  // 4. Build Rail UI
  const rail = document.createElement('div');
  rail.id = 'agy-voyager-rail';

  let currentActive = 0;
  let turnsCache = [];

  function scrollToTurn(idx) {
    const sc = getChatScroll();
    if (!sc || turnsCache.length === 0) return;
    const clamped = Math.max(0, Math.min(turnsCache.length - 1, idx));
    currentActive = clamped;
    const target = turnsCache[clamped];
    sc.scrollTo({ top: Math.max(0, target.offsetTop - 10), behavior: 'smooth' });
    updateActive(clamped);
  }

  // Button 1: Double Up (First turn)
  const firstBtn = document.createElement('div');
  firstBtn.className = 'v-btn double';
  firstBtn.innerText = '▲▲';
  firstBtn.title = '去第一个回复';
  firstBtn.onclick = () => {
    const sc = getChatScroll();
    if (sc) sc.scrollTo({ top: 0, behavior: 'smooth' });
    updateActive(0);
  };

  // Button 2: Single Up (Previous turn)
  const prevBtn = document.createElement('div');
  prevBtn.className = 'v-btn';
  prevBtn.innerText = '▲';
  prevBtn.title = '去上一个回复';
  prevBtn.onclick = () => {
    scrollToTurn(currentActive - 1);
  };

  const l1 = document.createElement('div'); l1.className = 'v-line';
  const dotsContainer = document.createElement('div'); dotsContainer.className = 'v-dots';
  const l2 = document.createElement('div'); l2.className = 'v-line';

  // Button 3: Single Down (Next turn)
  const nextBtn = document.createElement('div');
  nextBtn.className = 'v-btn';
  nextBtn.innerText = '▼';
  nextBtn.title = '去下一个回复';
  nextBtn.onclick = () => {
    scrollToTurn(currentActive + 1);
  };

  // Button 4: Double Down (Latest turn)
  const lastBtn = document.createElement('div');
  lastBtn.className = 'v-btn double';
  lastBtn.innerText = '▼▼';
  lastBtn.title = '去最新回复';
  lastBtn.onclick = () => {
    const sc = getChatScroll();
    if (sc) sc.scrollTo({ top: sc.scrollHeight, behavior: 'smooth' });
    updateActive(turnsCache.length - 1);
  };

  rail.append(firstBtn, prevBtn, l1, dotsContainer, l2, nextBtn, lastBtn);
  document.body.appendChild(rail);

  function updateActive(idx) {
    currentActive = idx;
    dotsContainer.querySelectorAll('.v-dot').forEach((d, i) => {
      d.classList.toggle('active', i === idx);
    });
  }

  function render() {
    turnsCache = getTurns();
    dotsContainer.innerHTML = '';

    if (turnsCache.length === 0) {
      const d = document.createElement('div');
