    target = [t for t in targets if t.get('type') == 'page'][0]

    async with websockets.connect(target['webSocketDebuggerUrl']) as ws:
        expr = '''
        (() => {
          const texts = Array.from(document.querySelectorAll('button, span, div, a')).map(el => (el.innerText || '').trim()).filter(Boolean);
          const chineseCount = texts.filter(t => /[\\u4e00-\\u9fa5]/.test(t)).length;
          return {
            chineseCount: chineseCount,
            totalTexts: texts.length,
            ratio: (chineseCount / texts.length * 100).toFixed(1) + '%'
          };
        })()
        '''
        msg = {'id': 1, 'method': 'Runtime.evaluate', 'params': {'expression': expr, 'returnByValue': True}}
        await ws.send(json.dumps(msg))
        res = await ws.recv()
        data = json.loads(res)
        print('i18n check:', json.dumps(data.get('result', {}).get('result', {}).get('value', {}), ensure_ascii=False))

asyncio.run(check_i18n())
