// ==UserScript==
// @name         Antigravity Voyager 对话时间轴导航器
// @namespace    https://antigravity.google/
// @version      5.0
// @description  为 Antigravity 对话窗口添加右侧极简时间轴进度条，支持四级箭头直达、精准定位提问起始行与视口常亮跟踪
// @author       Antigravity Pair Programmer
// @match        http://127.0.0.1:*/*
// @match        https://127.0.0.1:*/*
// @match        http://localhost:*/*
// @match        https://localhost:*/*
// @grant        none
// @run-at       document-start
// ==/UserScript==

(function () {
  'use strict';

  function safeInitVoyager() {
    try {
      const targetBody = document.body || document.documentElement;
      if (!targetBody) return false;

      if (document.getElementById('agy-voyager-rail')) return true;

      // 1. 样式注入
      let style = document.getElementById('agy-voyager-style');
      if (!style) {
        style = document.createElement('style');
        style.id = 'agy-voyager-style';
        (document.head || targetBody).appendChild(style);
      }
      style.textContent = `
        #agy-voyager-rail {
          position: fixed !important;
          right: 14px !important;
          top: 50% !important;
          transform: translateY(-50%) !important;
          display: flex !important;
          flex-direction: column !important;
          align-items: center !important;
          gap: 5px !important;
          z-index: 2147483647 !important;
          background: rgba(22, 24, 29, 0.88) !important;
          backdrop-filter: blur(14px) !important;
          -webkit-backdrop-filter: blur(14px) !important;
          padding: 7px 4px !important;
          border-radius: 20px !important;
          border: 1px solid rgba(255, 255, 255, 0.16) !important;
          box-shadow: 0 8px 30px rgba(0, 0, 0, 0.45) !important;
          opacity: 0.75;
          transition: opacity 0.2s ease;
          max-height: 82vh;
          user-select: none !important;
        }
        #agy-voyager-rail:hover { opacity: 1 !important; }
        .v-btn {
          width: 22px; height: 20px; display: flex; align-items: center; justify-content: center;
          cursor: pointer; color: rgba(255, 255, 255, 0.75); font-size: 11px; font-weight: bold;
          line-height: 1; border-radius: 4px; transition: background 0.15s, color 0.15s, transform 0.15s;
        }
        .v-btn:hover { color: #fff; background: rgba(255, 255, 255, 0.2); transform: scale(1.15); }
        .v-btn.double { font-size: 9px; letter-spacing: -1px; }
        .v-line { width: 12px; height: 1px; background: rgba(255, 255, 255, 0.12); margin: 2px 0; }
        .v-dots {
          display: flex; flex-direction: column; align-items: center; gap: 8px;
          max-height: calc(82vh - 120px); overflow-y: auto; padding: 4px 2px; scrollbar-width: none;
        }
        .v-dots::-webkit-scrollbar { display: none; }
        .v-dot {
          width: 9px; height: 9px; border-radius: 50%; background: rgba(255, 255, 255, 0.35);
          cursor: pointer; transition: background 0.15s ease, transform 0.15s ease; flex-shrink: 0;
        }
        .v-dot:hover { background: #3b82f6; transform: scale(1.4); }
        .v-dot.active {
          background: #10b981 !important; transform: scale(1.35) !important; box-shadow: none !important; animation: none !important;
        }
      `;

      // 2. 滚动容器与问答轮次查找
      function getChatScroll() {
        return document.querySelector('.overflow-y-auto.isolate') ||
               document.querySelector('.md-table-bleed') ||
               document.querySelector('[class*="overflow-y-auto"][class*="isolate"]');
      }

      function getTurns() {
        const sc = getChatScroll();
        if (!sc) return [];
        const list = sc.querySelector('.relative.flex.flex-col.gap-y-3') || sc.querySelector('.relative.w-full');
        if (list) {
          const items = Array.from(list.querySelectorAll(':scope > div.flex.items-start, :scope > div[class*="flex"][class*="items-start"]'));
          if (items.length > 0) return items;
        }
        const userPrompts = Array.from(sc.querySelectorAll('.md-sticky-message-bleed, [class*="user-input-step"]'));
        if (userPrompts.length > 0) return userPrompts;
        return [];
      }

      // 3. 构建时间轴 UI
      const rail = document.createElement('div');
      rail.id = 'agy-voyager-rail';

      let currentActive = 0;
      let turnsCache = [];

      function scrollToTurn(idx) {
        const sc = getChatScroll();
        if (!sc || turnsCache.length === 0) return;
        const clamped = Math.max(0, Math.min(turnsCache.length - 1, idx));
        currentActive = clamped;
        const target = turnsCache[clamped];
        sc.scrollTo({ top: Math.max(0, target.offsetTop - 10), behavior: 'smooth' });
        updateActive(clamped);
      }

      const firstBtn = document.createElement('div'); firstBtn.className = 'v-btn double'; firstBtn.innerText = '▲▲'; firstBtn.title = '去第一个回复';
      firstBtn.onclick = () => { const sc = getChatScroll(); if (sc) sc.scrollTo({ top: 0, behavior: 'smooth' }); updateActive(0); };

      const prevBtn = document.createElement('div'); prevBtn.className = 'v-btn'; prevBtn.innerText = '▲'; prevBtn.title = '去上一个回复';
      prevBtn.onclick = () => { scrollToTurn(currentActive - 1); };

      const l1 = document.createElement('div'); l1.className = 'v-line';
      const dotsContainer = document.createElement('div'); dotsContainer.className = 'v-dots';
      const l2 = document.createElement('div'); l2.className = 'v-line';

      const nextBtn = document.createElement('div'); nextBtn.className = 'v-btn'; nextBtn.innerText = '▼'; nextBtn.title = '去下一个回复';
      nextBtn.onclick = () => { scrollToTurn(currentActive + 1); };

      const lastBtn = document.createElement('div'); lastBtn.className = 'v-btn double'; lastBtn.innerText = '▼▼'; lastBtn.title = '去最新回复';
      lastBtn.onclick = () => { const sc = getChatScroll(); if (sc) sc.scrollTo({ top: sc.scrollHeight, behavior: 'smooth' }); updateActive(turnsCache.length - 1); };

      rail.append(firstBtn, prevBtn, l1, dotsContainer, l2, nextBtn, lastBtn);
      targetBody.appendChild(rail);

      function updateActive(idx) {
        currentActive = idx;
        dotsContainer.querySelectorAll('.v-dot').forEach((d, i) => d.classList.toggle('active', i === idx));
      }

      function render() {
        turnsCache = getTurns();
        dotsContainer.innerHTML = '';
        if (turnsCache.length === 0) {
          const d = document.createElement('div');
          d.className = 'v-dot active';
          dotsContainer.appendChild(d);
          return;
        }
        turnsCache.forEach((turn, i) => {
          const d = document.createElement('div');
          d.className = 'v-dot' + (i === currentActive ? ' active' : '');
          d.onclick = (e) => { e.stopPropagation(); scrollToTurn(i); };
          dotsContainer.appendChild(d);
        });
      }

      function syncScroll() {
        const sc = getChatScroll();
        if (!sc || turnsCache.length === 0) return;
        const curTop = sc.scrollTop;
        let bestIdx = 0;
        for (let i = 0; i < turnsCache.length; i++) {
          if (turnsCache[i].offsetTop <= curTop + 150) bestIdx = i;
        }
        updateActive(bestIdx);
      }

      let scrollAttached = false;
      function attachScroll() {
        const sc = getChatScroll();
        if (sc && !scrollAttached) {
          scrollAttached = true;
          let timer = null;
          sc.addEventListener('scroll', () => {
            if (timer) return;
            timer = setTimeout(() => { timer = null; syncScroll(); }, 50);
          }, { passive: true });
        }
      }

      let mTimer = null;
      const watcher = new MutationObserver(() => {
        clearTimeout(mTimer);
        mTimer = setTimeout(() => { render(); attachScroll(); syncScroll(); }, 300);
      });
      watcher.observe(targetBody, { childList: true, subtree: true });

      render();
      attachScroll();
      syncScroll();
      return true;
    } catch (e) {
      console.error('[Voyager Error]', e);
      return false;
    }
  }

  const bootstrap = () => { if (!safeInitVoyager()) setTimeout(safeInitVoyager, 300); };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bootstrap);
  else bootstrap();

  setTimeout(safeInitVoyager, 500);
  setTimeout(safeInitVoyager, 1500);
  setTimeout(safeInitVoyager, 3000);
})();

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

console.log('====================================================');
console.log('   Antigravity Voyager 对话时间轴跨平台一键安装器   ');
console.log('====================================================\n');

// 1. 自动探测 Antigravity 安装目录
function detectInstallDir() {
  const home = process.env.USERPROFILE || process.env.HOME || '';
  if (process.platform === 'win32') {
    const defaultWin = path.join(process.env.LOCALAPPDATA || path.join(home, 'AppData', 'Local'), 'Programs', 'antigravity');
    if (fs.existsSync(defaultWin)) return defaultWin;
  } else if (process.platform === 'darwin') {
    const defaultMac = '/Applications/Antigravity.app';
    if (fs.existsSync(defaultMac)) return defaultMac;
  } else {
    const linuxDirs = [
      path.join(home, 'Antigravity'),
      path.join(home, '.local', 'share', 'antigravity'),
      '/opt/Antigravity'
    ];
    for (const d of linuxDirs) {
      if (fs.existsSync(d)) return d;
    }
  }
  return null;
}

const installDir = detectInstallDir();
if (!installDir) {
  console.error('[错误] 未能自动定位到 Antigravity 安装目录，请确认软件已正确安装。');
  process.exit(1);
}
console.log('[探测] 成功识别到安装路径: ' + installDir);

// 2. 定位 resources 目录
let resourcesDir = path.join(installDir, 'resources');
if (process.platform === 'darwin') {
  resourcesDir = path.join(installDir, 'Contents', 'Resources');
}
if (!fs.existsSync(resourcesDir)) {
  console.error('[错误] 未找到 resources 资源目录: ' + resourcesDir);
  process.exit(1);
}

const asarPath = path.join(resourcesDir, 'app.asar');
const bakPath = path.join(resourcesDir, 'app.asar.bak');
if (!fs.existsSync(asarPath)) {
  console.error('[错误] 未找到核心文件 app.asar: ' + asarPath);
  process.exit(1);
}

// 3. 安全备份
if (!fs.existsSync(bakPath)) {
  console.log('[备份] 正在创建官方原始备份: app.asar.bak ...');
  fs.copyFileSync(asarPath, bakPath);
  console.log('[备份] 备份创建成功！');
} else {
  console.log('[备份] 已存在历史备份文件，跳过备份。');
}

// 4. 解包
const tempDir = path.join(__dirname, '_temp_unpack');
if (fs.existsSync(tempDir)) fs.rmSync(tempDir, { recursive: true, force: true });

console.log('[解包] 正在使用 asar 提取 app.asar ...');
try {
  execSync(`npx -y @electron/asar extract "${asarPath}" "${tempDir}"`, { stdio: 'inherit' });
} catch (e) {
  console.error('[错误] 解包失败，请检查是否已安装 Node.js 和网络环境。');
  process.exit(1);
}

// 5. 注入 Voyager 代码到 preload.js
const preloadPath = path.join(tempDir, 'dist', 'preload.js');
if (!fs.existsSync(preloadPath)) {
  console.error('[错误] 解包后未找到 dist/preload.js');
  fs.rmSync(tempDir, { recursive: true, force: true });
  process.exit(1);
}

const voyagerSourcePath = path.join(__dirname, 'voyager_core.js');
let voyagerCode = '';
if (fs.existsSync(voyagerSourcePath)) {
  voyagerCode = fs.readFileSync(voyagerSourcePath, 'utf-8');
} else {
  console.error('[错误] 找不到 voyager_core.js 核心代码文件！');
  fs.rmSync(tempDir, { recursive: true, force: true });
  process.exit(1);
}

console.log('[修改] 正在向 preload.js 注入 Voyager 导航条引擎...');
let preloadContent = fs.readFileSync(preloadPath, 'utf-8');

// 幂等标记防重复注入
const VOYAGER_MARKER = '/* --- ANTIGRAVITY VOYAGER TIMELINE NAVIGATOR --- */';
if (preloadContent.includes(VOYAGER_MARKER)) {
  // 清洗旧版
  const regex = new RegExp('/\\* --- ANTIGRAVITY VOYAGER TIMELINE NAVIGATOR --- \\*/[\\s\\S]*?/\\* --- VOYAGER END --- \\*/', 'g');
  preloadContent = preloadContent.replace(regex, '');
}

const injectPayload = `\n\n${VOYAGER_MARKER}\n${voyagerCode}\n/* --- VOYAGER END --- */\n`;
preloadContent += injectPayload;
fs.writeFileSync(preloadPath, preloadContent, 'utf-8');

// 语法检查
try {
  execSync(`node --check "${preloadPath}"`);
  console.log('[门禁] preload.js 语法校验通过！');
} catch (e) {
  console.error('[错误] 注入后语法检查未通过，已中止安装。');
  fs.rmSync(tempDir, { recursive: true, force: true });
  process.exit(1);
}

// 6. 重新打包
const tempAsar = path.join(__dirname, 'app.asar.temp');
if (fs.existsSync(tempAsar)) fs.unlinkSync(tempAsar);

console.log('[打包] 正在重新编译并打包 app.asar ...');
try {
  execSync(`npx -y @electron/asar pack "${tempDir}" "${tempAsar}"`, { stdio: 'inherit' });
} catch (e) {
  console.error('[错误] 打包新 asar 失败: ' + e.message);
  fs.rmSync(tempDir, { recursive: true, force: true });
  process.exit(1);
}

// 7. 部署并清理
console.log('[部署] 正在原子替换系统文件...');
try {
  fs.copyFileSync(tempAsar, asarPath);
  fs.unlinkSync(tempAsar);
  fs.rmSync(tempDir, { recursive: true, force: true });
  console.log('\n🎉 [成功] Antigravity Voyager 导航器已在当前设备上成功安装！');
  console.log('💡 重新启动 Antigravity 客户端即可享受全新的右侧四级时间轴导航！\n');
} catch (e) {
  console.error('[错误] 覆盖文件失败 (请先退出正在运行的 Antigravity 客户端): ' + e.message);
}

