            scrollToTurn(i);
          };
          dotsContainer.appendChild(d);
        });
      }

      function syncScroll() {
        const sc = getChatScroll();
        if (!sc || turnsCache.length === 0) return;
        const curTop = sc.scrollTop;
        let bestIdx = 0;
        for (let i = 0; i < turnsCache.length; i++) {
          if (turnsCache[i].offsetTop <= curTop + 150) {
            bestIdx = i;
          }
        }
        updateActive(bestIdx);
      }

      let scrollAttached = false;
      function attachScroll() {
        const sc = getChatScroll();
        if (sc && !scrollAttached) {
          scrollAttached = true;
          let timer = null;
          sc.addEventListener('scroll', () => {
            if (timer) return;
            timer = setTimeout(() => {
              timer = null;
              syncScroll();
            }, 50);
          }, { passive: true });
        }
      }

      let mTimer = null;
      const watcher = new MutationObserver(() => {
        clearTimeout(mTimer);
        mTimer = setTimeout(() => {
          render();
          attachScroll();
          syncScroll();
        }, 300);
      });
      watcher.observe(targetBody, { childList: true, subtree: true });

      render();
      attachScroll();
      syncScroll();
      return true;
    } catch (e) {
      console.error('[agyChatLadder Error]', e);
      return false;
    }
  }

  // 多阶定时器异步兜底挂载 (防冷启动白屏)
  const bootstrap = () => {
    if (!safeInitLadder()) {
      setTimeout(safeInitLadder, 300);
    }
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bootstrap);
  } else {
    bootstrap();
  }

  setTimeout(safeInitLadder, 500);
  setTimeout(safeInitLadder, 1200);
  setTimeout(safeInitLadder, 2500);
  setTimeout(safeInitLadder, 5000);
  console.log('[agyChatLadder] 天梯导航系统已就绪！');
})();

