const LADDER_SIGN_START = "/* --- AGY CHAT LADDER START --- */";
const LADDER_SIGN_END = "/* --- AGY CHAT LADDER END --- */";

function cleanJsContent(content) {
    let res = content;
    const regex = new RegExp(escapeRegExp(SIGNATURE_START) + "[\\s\\S]*?" + escapeRegExp(SIGNATURE_END), "g");
    res = res.replace(regex, "");
    const regexLadder = new RegExp(escapeRegExp(LADDER_SIGN_START) + "[\\s\\S]*?" + escapeRegExp(LADDER_SIGN_END), "g");
    res = res.replace(regexLadder, "");
    const regexOldLadder = /\/\* --- AGY CHAT LADDER TIMELINE ENGINE --- \*\/[\s\S]*?\/\* --- LADDER END --- \*\//g;
    res = res.replace(regexOldLadder, "");
    const regexOldVoyager = /\/\* --- VOYAGER TIMELINE NAVIGATOR --- \*\/[\s\S]*?\/\* --- VOYAGER END --- \*\//g;
    res = res.replace(regexOldVoyager, "");
    return res;
}

