const ws = new WebSocket('ws://127.0.0.1:49279/devtools/page/FEA6D3D5FCAB779D91D0FE62EAAECAE7');

ws.addEventListener('open', () => {
  ws.send(JSON.stringify({ id: 1, method: 'Console.enable' }));
  ws.send(JSON.stringify({ id: 2, method: 'Runtime.enable' }));
  ws.send(JSON.stringify({ id: 3, method: 'Log.enable' }));

  // Reload the page to capture everything from the very first millisecond of load!
  setTimeout(() => {
    ws.send(JSON.stringify({ id: 4, method: 'Page.reload' }));
  }, 500);
});

ws.addEventListener('message', (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.method === 'Runtime.consoleAPICalled') {
    const type = msg.params.type;
    const args = msg.params.args.map(a => a.value || a.description || JSON.stringify(a)).join(' ');
    console.log(`[CONSOLE ${type.toUpperCase()}]`, args);
  } else if (msg.method === 'Runtime.exceptionThrown') {
    console.log(`[EXCEPTION]`, JSON.stringify(msg.params.exceptionDetails));
  } else if (msg.method === 'Log.entryAdded') {
    console.log(`[LOG ${msg.params.entry.level}]`, msg.params.entry.text);
  }
});

setTimeout(() => {
  process.exit(0);
}, 5000);

