const asar = require('@electron/asar');
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const officialBak = 'C:\\Users\\wangRui\\AppData\\Local\\Programs\\antigravity\\resources\\app.asar.official.bak';
const realUnpacked = 'C:\\Users\\wangRui\\AppData\\Local\\Programs\\antigravity\\resources\\app.asar.unpacked';
const targetAsar = 'C:\\Users\\wangRui\\AppData\\Local\\Programs\\antigravity\\resources\\app.asar';

const workDir = path.join(__dirname, '_temp_full_build');
const extractedDir = path.join(workDir, 'extracted');
const outputAsar = path.join(workDir, 'app.asar.out');

async function build() {
  try {
    if (fs.existsSync(workDir)) fs.rmSync(workDir, { recursive: true, force: true });
    fs.mkdirSync(workDir, { recursive: true });

    // 1. Setup official base + unpacked
    console.log('[1/6] 准备官方原始文件与 unpacked 目录...');
    const tempBakAsar = path.join(workDir, 'app.asar');
    const tempUnpacked = path.join(workDir, 'app.asar.unpacked');
    fs.copyFileSync(officialBak, tempBakAsar);
    fs.cpSync(realUnpacked, tempUnpacked, { recursive: true });

    // 2. 解包官方 asar
    console.log('[2/6] 正在精确提取官方 asar...');
    asar.extractAll(tempBakAsar, extractedDir);

    // 3. 准备汉化代码
    console.log('[3/6] 正在生成完整中文汉化代码...');
    const cnEnginePath = 'C:\\Users\\wangRui\\AppData\\Local\\Programs\\antigravity2-cn\\localization_engine.js';
    // Load dicts from antigravity2-cn
    const dictsDir = 'C:\\Users\\wangRui\\AppData\\Local\\Programs\\antigravity2-cn\\dicts';
    const dict = {};
    if (fs.existsSync(dictsDir)) {
      for (const f of fs.readdirSync(dictsDir)) {
        if (f.endsWith('.json')) {
          const d = JSON.parse(fs.readFileSync(path.join(dictsDir, f), 'utf8'));
          Object.assign(dict, d);
        }
      }
    }
    console.log(`已加载 ${Object.keys(dict).length} 条中文翻译词条`);

    // 4. 注入 preload.js (汉化 + AgyChatLadder)
    console.log('[4/6] 正在注入 preload.js (汉化与 AgyChatLadder)...');
    const preloadPath = path.join(extractedDir, 'dist', 'preload.js');
    let preloadContent = fs.readFileSync(preloadPath, 'utf8');

    // Load localization JS from localization_engine.js
    const cnEngineCode = fs.readFileSync(cnEnginePath, 'utf8');
    // Extract generateJs from localization_engine.js
    const genJsFn = new Function('require', '__dirname', 'fs', 'path', `
      ${cnEngineCode}
      return generateJs();
    `);
    const translationJs = genJsFn(require, 'C:\\Users\\wangRui\\AppData\\Local\\Programs\\antigravity2-cn', fs, path);

    // Load latest AgyChatLadder
    const ladderPath = 'D:\\code\\Antigravity_files\\AgyChatLadder\\chat_ladder_core.js';
    const ladderCode = fs.readFileSync(ladderPath, 'utf8');

    preloadContent += `\n\n/* --- ANTIGRAVITY CHINESE LOCALIZATION START --- */\n${translationJs}\n/* --- ANTIGRAVITY CHINESE LOCALIZATION END --- */\n`;
    preloadContent += `\n\n/* --- AGY CHAT LADDER TIMELINE ENGINE --- */\n${ladderCode}\n/* --- LADDER END --- */\n`;
    fs.writeFileSync(preloadPath, preloadContent, 'utf8');

    // 语法检查
    execSync(`node --check "${preloadPath}"`);
    console.log('preload.js 语法校验 100% 通过！');

    // 5. 汉化 menu.js, tray.js, loadingOverlay.js, updater.js
    console.log('[5/6] 正在汉化系统菜单与任务栏...');
    const menuPath = path.join(extractedDir, 'dist', 'menu.js');
    const trayPath = path.join(extractedDir, 'dist', 'tray.js');
    const loadingPath = path.join(extractedDir, 'dist', 'loadingOverlay.js');
    const updaterPath = path.join(extractedDir, 'dist', 'updater.js');

    // We can run the patch functions from localization_engine
    const patchMainFilesFn = new Function('require', '__dirname', 'fs', 'path', 'tempDir', `
      ${cnEngineCode}
      // run menu patch
      let menuContent = fs.readFileSync('${menuPath.replace(/\\/g, '/')}', 'utf8');
      const menuCleaned = cleanMenuJsContent(menuContent);
      const patchedMenu = injectMenuTranslations(menuCleaned);
      fs.writeFileSync('${menuPath.replace(/\\/g, '/')}', patchedMenu, 'utf8');

      // run tray patch
      let trayContent = fs.readFileSync('${trayPath.replace(/\\/g, '/')}', 'utf8');
      const trayCleaned = cleanTrayJsContent(trayContent);
      const patchedTray = injectTrayTranslations(trayCleaned);
      fs.writeFileSync('${trayPath.replace(/\\/g, '/')}', patchedTray, 'utf8');
    `);
    patchMainFilesFn(require, 'C:\\Users\\wangRui\\AppData\\Local\\Programs\\antigravity2-cn', fs, path, extractedDir);
    console.log('系统菜单与任务栏汉化注入成功！');

    // 6. 完美重新打包 (带 --unpack-dir "**/chrome-devtools-mcp")
    console.log('[6/6] 正在使用标准 unpack-dir 规则编译打包 app.asar...');
    await asar.createPackageWithOptions(extractedDir, outputAsar, {
      unpackDir: '**/chrome-devtools-mcp'
    });

    const stat = fs.statSync(outputAsar);
    console.log('🎉 编译大获成功！产物体积:', (stat.size / 1024 / 1024).toFixed(2), 'MB (完美轻量级)');

    // 原子部署
    console.log('正在原子替换正式系统文件...');
    fs.copyFileSync(outputAsar, targetAsar);
    console.log('✅ 系统 app.asar 部署完成！');
  } catch(e) {
    console.error('构建失败:', e);
  } finally {
    if (fs.existsSync(workDir)) fs.rmSync(workDir, { recursive: true, force: true });
  }
}

build();

