                            dotsCount: r.querySelectorAll('.ladder-dot-wrap').length,
                            tipsCount: r.querySelectorAll('.ladder-tooltip').length
                        });
                    });
                    return {
                        railsCount: rails.length,
                        totalDots: dots.length,
                        totalTips: tips.length,
                        railDetails: info,
                        firstTipText: tips.length > 0 ? tips[0].innerHTML : 'none'
                    };
                })()''',
                'returnByValue': True
            }
        }
        await ws.send(json.dumps(cmd))
        res = await ws.recv()
