    async with websockets.connect(ws_url) as ws:
        js = """(() => {
            const rail = document.querySelector('.agy-chat-ladder-rail');
            if (!rail) return 'no rail';
            window.__removeStack = null;
            const origRemove = rail.remove;
            rail.remove = function() {
                window.__removeStack = new Error().stack;
                console.error('[RAIL REMOVED]', window.__removeStack);
                return origRemove.apply(this, arguments);
            };
            return 'hooked';
        })()"""
