# -*- coding: utf-8 -*-
import os

content = '''/**
 * AgyChatLadder (对话天梯) - v2.0.0 (纯净极简版)
 * Antigravity 专属长对话微型时间轴与四级天梯导航引擎（极致纯粹、零浮层、零闪烁、支持多分屏与叠层图标）
 * GitHub: https://github.com/SuperRui0122/AgyChatLadder
 * 
 * - 纯净零浮层: 彻底移除所有停留悬浮卡片与弹窗，无任何视觉遮挡，回归极致清爽
 * - 图标规范: 登顶首提为上下双重 ^ 叠层, 上一问为单 ^, 下一问为单 v, 触底最新为双重 v 叠层
 * - 多分屏感知: 自动识别左右/上下分屏视口，各自独立挂载专属天梯与滚动控制器
 * - 原生隔离容器 offsetTop 毫秒级原生平滑滚动
 * - 静态常亮翠绿踏板圆点，触感稳健，无晃眼闪烁
 */
(function () {
  'use strict';

  function initLadderSystem() {
    try {
