import os, urllib.request, json, asyncio, websockets

port_file = os.path.expandvars(r'%APPDATA%\Antigravity\DevToolsActivePort')
with open(port_file) as f:
    port = int(f.read().splitlines()[0])

async def test():
    url = f'http://127.0.0.1:{port}/json'
    with urllib.request.urlopen(url, timeout=5) as resp:
        targets = json.loads(resp.read().decode('utf-8'))
    page = next(t for t in targets if t.get('type') == 'page')
    ws_url = page['webSocketDebuggerUrl']

    async with websockets.connect(ws_url) as ws:
        js = """(() => {
            const sc = document.querySelector('.overflow-y-auto.isolate');
            if (!sc) return 'no sc';
            const bleeds = Array.from(sc.querySelectorAll('.md-sticky-message-bleed'));
            return bleeds.map((it, idx) => {
                let raw = (it.textContent || '').trim().replace(/\\s+/g, ' ');
                raw = raw.replace(/\\d{1,2}:\\d{2}\\s*$/, '').trim();
                let curr = it;
                let totalTop = 0;
                while (curr && curr !== sc) {
                    totalTop += curr.offsetTop;
                    curr = curr.offsetParent;
                }
                return {
                    turn: idx + 1,
                    text: raw.length > 55 ? raw.slice(0, 55) + '...' : raw,
                    totalTop: totalTop
                };
            });
        })()"""
